KINDS = ("verb", "phrase", "trait")
REPEATS_OK = {"handled", "organized", "supported", "trained"}      # written before the one-group rule; each repeats a single word
FIRST = 19                                                          # the first pages, written before pick lists had to quote the groups


def test():
    import re
    slugs = [x["slug"] for x in WORDS]
    assert len(slugs) == len(set(slugs)) >= 150
    seen_lines, seen_q = set(), set()
    for i, x in enumerate(WORDS):
        assert x["slug"] == re.sub(r"[^a-z]+", "-", x["word"]).strip("-"), x["slug"]
        assert len(x["word"]) <= 34, x["slug"]                      # "Another Word for “…” on a Resume" stays within 65 characters
        assert x.get("kind", "verb") in KINDS, x["slug"]
        assert x["why"].endswith(".") and 8 <= len(x["why"].split()) <= 40, x["slug"]
        assert 4 <= len(x["groups"]) <= 7 and len(x["qa"]) >= 2, x["slug"]
        every = [w for _, words, _ in x["groups"] for w in words]
        assert x["word"] not in every, x["slug"]
        assert len(every) == len(set(every)) or x["slug"] in REPEATS_OK, (x["slug"], sorted(w for w in set(every) if every.count(w) > 1))
        assert len({what for what, _, _ in x["groups"]}) == len(x["groups"]), x["slug"]
        for what, words, line in x["groups"]:
            assert len(words) == 6 == len(set(words)) and any(c.isdigit() for c in line) and not line.endswith("."), (x["slug"], what)
            assert all(w == w.strip() and 1 <= len(w.split()) <= 3 for w in words), (x["slug"], what)
            assert line.split()[0].lower().rstrip(",") in [w.split()[0] for w in words] or line.split()[0].lower() in ("ran", "co-designed"), (x["slug"], line)
            assert line not in seen_lines and 6 <= len(line.split()) <= 32, (x["slug"], line)
            seen_lines.add(line)
        for q, a in x["qa"]:
            assert q.endswith("?") and 12 <= len(a.split()) <= 60, (x["slug"], q)
            assert a.rstrip("”").endswith((".", "?")), (x["slug"], q)
        assert len({q for q, _ in x["qa"]}) == len(x["qa"]), x["slug"]
        if i >= FIRST:                                              # a question is answered on one page, not on two
            assert not seen_q & {q for q, _ in x["qa"]}, (x["slug"], seen_q & {q for q, _ in x["qa"]})
        seen_q |= {q for q, _ in x["qa"]}
        if "pick" in x:
            assert 3 <= len(x["pick"]) <= 5, x["slug"]
            for did, words in x["pick"]:
                assert did and not did.endswith(".") and len(words.split(", ")) >= 2, (x["slug"], did)
                assert i < FIRST or all(w in every for w in words.split(", ")), (x["slug"], did, words)
        if "before_after" in x:
            assert 2 <= len(x["before_after"]) <= 3, x["slug"]
            for weak, strong in x["before_after"]:
                assert weak != strong and any(c.isdigit() for c in strong) and not strong.endswith("."), (x["slug"], strong)
                assert strong not in seen_lines and not weak.endswith("."), (x["slug"], strong)
                seen_lines.add(strong)
    kinds = [x.get("kind", "verb") for x in WORDS]
    print(f"resume_words: {len(WORDS)} words ({kinds.count('verb')} verbs, {kinds.count('phrase')} phrases, {kinds.count('trait')} traits), all checks passed")


if __name__ == "__main__":
    test()
